import{_ as e,c as t,o,a2 as a}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"Page layouts","description":"","frontmatter":{"sidebarPos":6,"sidebarTitle":"Page layouts","sidebarGroupTitle":"Cms","outline":"deep"},"headers":[],"relativePath":"guide/cms/page-layouts.md","filePath":"guide/cms/page-layouts.md","lastUpdated":1784841066000}'),d={name:"guide/cms/page-layouts.md"},l=a('<h1 id="page-layouts" tabindex="-1">Page layouts <a class="header-anchor" href="#page-layouts" aria-label="Permalink to &quot;Page layouts&quot;">​</a></h1><p>A <strong>PageLayout</strong> is the locale-agnostic presentation binding for one routed model class (e.g. all <code>Blog</code> posts share one shell). URLs stay on <a href="./parent-segments-and-url-routes">Parent segments &amp; URL routes</a>; HTML chrome comes from an optional <a href="./layout-builders">LayoutBuilder</a> plus per-model appends.</p><p>Models opt in via <code>HasPageLayout</code> (on <code>IsCmr</code>). Resolve with <code>CmsPageLayoutResolver</code>.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>target_model_class</code></td><td>FQCN of the CMR model (unique)</td></tr><tr><td><code>layout_builder_id</code></td><td>Optional LayoutBuilder for the document shell</td></tr><tr><td><code>blade_source</code></td><td><code>db</code> or <code>filesystem</code> for <strong>this binding’s appends</strong></td></tr><tr><td><code>blade_segments</code></td><td>DB appends: <code>head</code> / <code>body</code> / <code>footer</code> when <code>blade_source=db</code></td></tr><tr><td><code>blade_view_name</code></td><td><strong>Optional</strong> explicit view. Often <strong><code>NULL</code></strong> — then filesystem falls back by module/route (below)</td></tr></tbody></table><p>When <code>blade_source</code> is omitted on the row, resolution falls back to <code>cms_layout_builder.default_blade_source</code> (<strong><code>db</code></strong> by default).</p><h2 id="how-it-wraps-a-page" tabindex="-1">How it wraps a page <a class="header-anchor" href="#how-it-wraps-a-page" aria-label="Permalink to &quot;How it wraps a page&quot;">​</a></h2><p><code>CmsPageLayoutPresentationWrapper</code> on public render:</p><ol><li>Inner content — prefer <code>module::route.custom</code> when present</li><li>PageLayout appends (DB segments <strong>or</strong> filesystem <code>page_layout</code> blades)</li><li>Wrap with LayoutBuilder shell (<code>LayoutBladeResolver</code>) + <a href="./stylesheets">stylesheet</a> links</li></ol><p>If there is <strong>no</strong> enabled PageLayout row, module filesystem <code>page_layout</code> segments can still merge when <code>cms_page_layouts.filesystem_segments_without_db_binding_enabled</code> is <strong>true</strong> (default).</p><h2 id="null-blade-view-name-→-module-route-filesystem-fallback" tabindex="-1">NULL <code>blade_view_name</code> → module/route filesystem fallback <a class="header-anchor" href="#null-blade-view-name-→-module-route-filesystem-fallback" aria-label="Permalink to &quot;NULL `blade_view_name` → module/route filesystem fallback&quot;">​</a></h2><p>This is the usual production pattern: the <code>page_layouts</code> row exists (target model + layout builder), but <strong><code>blade_view_name</code> is empty</strong>. Markup lives in the module under <code>{route}/page_layout/</code>.</p><p>Context comes from the presentation view name (e.g. <code>blog::blog.custom</code> → module <code>blog</code>, route <code>blog</code>):</p><table><thead><tr><th>Priority</th><th>View name</th><th>Disk path</th></tr></thead><tbody><tr><td>1</td><td><code>vendor.modularous.modules.{module}.{route}.page_layout.{segment}</code></td><td><code>resources/views/vendor/modularous/modules/{module}/{route}/page_layout/{segment}.blade.php</code></td></tr><tr><td>2</td><td><code>modularous::modules.{module}.{route}.page_layout.{segment}</code></td><td>package / published modularous views</td></tr><tr><td>3</td><td><strong><code>{module}::{route}.page_layout.{segment}</code></strong></td><td><strong><code>modules/{Module}/Resources/views/{route}/page_layout/{segment}.blade.php</code></strong></td></tr></tbody></table><p><code>{segment}</code> = <code>head</code> | <code>body</code> | <code>footer</code>.</p><h3 id="example-blog-post-detail" tabindex="-1">Example: Blog post detail <a class="header-anchor" href="#example-blog-post-detail" aria-label="Permalink to &quot;Example: Blog post detail&quot;">​</a></h3><p>DB (<code>page_layouts</code>):</p><table><thead><tr><th>target_model_class</th><th>blade_view_name</th><th>admin_label</th></tr></thead><tbody><tr><td><code>Modules\\Blog\\Entities\\Blog</code></td><td><strong><code>NULL</code></strong></td><td>Blog Post Detail</td></tr></tbody></table><p>Filesystem fallback:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>blog::blog.page_layout.body</span></span>\n<span class="line"><span>→ modules/Blog/Resources/views/blog/page_layout/body.blade.php</span></span></code></pre></div><p>Landing rows often set an <strong>explicit</strong> <code>blade_view_name</code> instead (e.g. <code>blog::blog_landing.page_layout.body</code>) — same convention, just stored on the row.</p><p>Convention: <strong>snake module namespace + snake route folder</strong> = submodule view root (<code>Blog</code> module / <code>Blog</code> route → <code>blog::blog.*</code>).</p><p>After editing views: <code>php artisan view:clear</code>.</p><h2 id="default-layoutbuilder-shell" tabindex="-1">Default LayoutBuilder shell <a class="header-anchor" href="#default-layoutbuilder-shell" aria-label="Permalink to &quot;Default LayoutBuilder shell&quot;">​</a></h2><p>When a PageLayout has no <code>layout_builder_id</code> (or static segments need a shell):</p><ol><li><code>cms_page_layouts.default_layout_builder_id</code> if set</li><li>Else LayoutBuilder with slug = <code>cms_layout_builder.default_layout_slug</code> (if non-empty)</li></ol><h2 id="informational-fallback" tabindex="-1">Informational fallback <a class="header-anchor" href="#informational-fallback" aria-label="Permalink to &quot;Informational fallback&quot;">​</a></h2><p>If neither <code>module::route.custom</code> nor static page_layout body exists:</p><table><thead><tr><th>Key</th><th>Default</th></tr></thead><tbody><tr><td><code>public_presentation_informational_fallback_enabled</code></td><td><code>true</code></td></tr><tr><td><code>public_presentation_informational_fallback_view</code></td><td><code>cms::page.page_layout.body</code></td></tr></tbody></table><h2 id="config-modularous-cms-page-layouts" tabindex="-1">Config (<code>modularous.cms_page_layouts</code>) <a class="header-anchor" href="#config-modularous-cms-page-layouts" aria-label="Permalink to &quot;Config (`modularous.cms_page_layouts`)&quot;">​</a></h2><table><thead><tr><th>Key</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>Feature on/off</td></tr><tr><td><code>filesystem_segments_without_db_binding_enabled</code></td><td><code>true</code></td><td>Use <code>{module}::{route}.page_layout.*</code> without a DB row</td></tr><tr><td><code>default_layout_builder_id</code></td><td><code>null</code></td><td>Fallback LayoutBuilder id</td></tr><tr><td><code>layout_appends_modal_preview_enabled</code></td><td><code>true</code></td><td>Modal draft preview for appends</td></tr><tr><td><code>public_presentation_informational_fallback_enabled</code></td><td><code>true</code></td><td>Inner body fallback</td></tr><tr><td><code>public_presentation_informational_fallback_view</code></td><td><code>cms::page.page_layout.body</code></td><td>Fallback Blade</td></tr></tbody></table><p>See <a href="./configuration">Configuration</a>. Stylesheets and LayoutBuilder blades: <a href="./stylesheets">Stylesheets</a>, <a href="./layout-builders">Layout builders</a>.</p>',32),s=[l];function r(c,n,i,u,p,h){return o(),t("div",null,s)}const m=e(d,[["render",r]]);export{b as __pageData,m as default};
